'use strict';

// MODULES //

var readFile = require( 'node:fs/promises' ).readFile;
var validateRegistry = require( '@data-apis/registry/validate' );


// MAIN //

/**
* Reads and validates a registry file.
*
* @param {string} filePath - registry path
* @returns {Promise<Object>} registry
*/
async function loadRegistry( filePath ) {
	var registry;

	try {
		registry = JSON.parse( await readFile( filePath, 'utf8' ) );
	} catch ( error ) {
		throw new Error( 'Unable to read registry ' + filePath + ': ' + error.message, {
			'cause': error
		} );
	}
	return validateRegistry( registry );
}


// EXPORTS //

module.exports = loadRegistry;
